      let azH = az - s.eye.x * 0.2;
      let elH = el + s.eye.y * 0.09;
      let colH = i32(floor(azH / tx + cx));
      let hillRows = i32(s.mi.z);
      let rowH = max(0, i32(floor((elH - s.mj.y * s.mv.y) / tx)));
